import {router,usePathname,type Href} from 'expo-router';import {useDemoOffice} from './useDemoOffice';import DeviceReview,{DeviceReviewList} from './DeviceReview';import DeviceRecordPanel from './DeviceRecordPanel';import RecordEditor from '../records/RecordEditor';import {mutationCommands} from '../../shared/demoCommands';import {demoId} from '../../shared/demoRecords';import {financialSummary,auditRecords,day} from '../../shared/business';import Workspace from '../../features/workspace/Workspace';import AgentWorkspace from '../../features/agents/AgentWorkspace';import {agents as specialistAgents} from '../../shared/agents';import * as DocumentPicker from 'expo-document-picker';import * as Speech from 'expo-speech';
import {Sparkle,Microphone,Files,DotsThree,Receipt,CheckCircle,ListChecks,Buildings,GearSix,ArrowUpRight,ArrowRight,ArrowUp,Plus,X,Paperclip,SpeakerHigh,ShieldCheck,CaretRight,WarningCircle,Clock,Check,MagnifyingGlass,MapPin,ArrowCounterClockwise,DownloadSimple,House,ChatCircle,UserCircle,Bell,SlidersHorizontal,ArrowLeft,EnvelopeSimple,LinkSimple} from 'phosphor-react-native';
import {seed,today} from '../../data';import {activityDay,activityTime} from '../../activity';import {checkBill,transitionApproval} from '../../domain.mjs';import {api} from '../../api';import {saveFile,readFile,readTextFile,shareDoc} from '../../files';import {voiceRoute} from '../../voiceRoute';import VoiceSheet from '../../VoiceSheet';
